import json
H,W=29,23
g=[[1]*W for _ in range(H)]
markers={13:list(range(10,19))+[20,21],14:[10,13,21],15:[10,21],16:[10,13,21],17:[10,13,21],18:[10,21],19:[10,21],20:[10,21],21:[10,21],22:[10,21],23:list(range(10,22))}
for r,cs in markers.items():
    for c in cs:g[r][c]=3
# On each row/column with >=3 markers, bridge all strict gaps between consecutive markers.
for r in range(H):
    cs=[c for c,v in enumerate(g[r]) if v==3]
    if len(cs)>=3:
        for a,b in zip(cs,cs[1:]):
            for c in range(a+1,b):g[r][c]=2
for c in range(W):
    rs=[r for r in range(H) if g[r][c]==3]
    if len(rs)>=3:
        for a,b in zip(rs,rs[1:]):
            for r in range(a+1,b):g[r][c]=2
assert len(g)==29 and all(len(row)==23 for row in g)
assert set(v for row in g for v in row) <= {1,2,3}
s=json.dumps({'action':'submit','grid':g},separators=(',',':'))
o=json.loads(s); assert len(o['grid'])==29 and all(len(row)==23 for row in o['grid'])
print('added=',[(r,c) for r in range(H) for c in range(W) if g[r][c]==2])
print(s)
